(function attachDynamicPlayEngine(YEAR_KEY) {
  const data = window.curriculumData && window.curriculumData[YEAR_KEY];
  if (!data) return;

  const AR_DIGITS = "٠١٢٣٤٥٦٧٨٩";
  const toAr = (n) => String(n).replace(/\d/g, d => AR_DIGITS[d]);
  const fromAr = (s) => parseInt(String(s).replace(/[٠-٩]/g, d => AR_DIGITS.indexOf(d)).replace(/[^\d]/g, ""), 10);

  function shuffle(arr) {
    const a = arr.slice();
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  }

  function pickWrongs(pool, excludeList, count) {
    const ex = new Set(excludeList);
    const filtered = shuffle(pool.filter(x => x && !ex.has(x)));
    const out = [];
    for (const item of filtered) {
      if (!out.includes(item)) out.push(item);
      if (out.length >= count) break;
    }
    while (out.length < count) out.push("خِيَارٌ آخَرْ");
    return out;
  }

  function makeOpts(correct, wrongs) {
    const opts = [{ text: correct, correct: true }];
    wrongs.slice(0, 3).forEach(w => opts.push({ text: w, correct: false }));
    return shuffle(opts);
  }

  function wrongNums(ansStr) {
    const v = fromAr(ansStr);
    const base = isNaN(v) ? 5 : v;
    const cands = shuffle([base + 1, base + 2, Math.max(1, base - 1), base + 5, base + 10, Math.max(0, base - 2)]);
    const res = [];
    for (const c of cands) {
      const s = toAr(c);
      if (s !== ansStr && !res.includes(s)) res.push(s);
      if (res.length === 3) break;
    }
    return res;
  }

  const pools = { prophets: [], virtues: [], letters: [], grammar: [], sci: [], sciAnswers: [], rights: [], sports: [], words: [] };
  Object.keys(data).forEach(wk => {
    const u = data[wk];
    if (!u || !u["1"]) return;
    const s1 = u["1"].play._qSeed;
    if (s1) {
      pools.prophets.push(s1.prophet);
      pools.virtues.push(s1.virtue);
      pools.letters.push(`حَرْفُ (${s1.ltr})`);
      (s1.kws || []).forEach(k => pools.words.push(k));
    }
    const s2 = u["2"].play._qSeed;
    if (s2 && s2.topic) pools.grammar.push(s2.topic);
    if (s2 && s2.init) [].concat(s2.init, s2.med, s2.fin).forEach(w => pools.words.push(w));
    const s5 = u["5"].play._qSeed;
    if (s5 && s5.actions) s5.actions.forEach(a => pools.sports.push(a));
    const s6 = u["6"].play._qSeed;
    if (s6 && s6.pairs) s6.pairs.forEach(p => { pools.sci.push(p[0]); pools.sciAnswers.push(p[1]); });
    const s7 = u["7"].play._qSeed;
    if (s7 && s7.right) pools.rights.push(s7.right);
  });

  const BAD_ETHICS = ["الكَسَلْ", "الغَضَبْ", "العِنَادْ", "الإِهْمَالْ", "الإِسْرَافْ", "الغِشّْ", "التَّكَبُّرْ"];

  function generatePlayData(wk, sk, seed) {
    const img = seed.img || "";
    let qPool = [];
    let pairs = [];
    let decoy = "خِيَارٌ خَاطِئْ";
    let basket = null;

    if (seed.type === "story") {
      qPool.push({
        img, focusWord: seed.prophet,
        q: `مَا الخُلُقُ البَارِزُ فِي قِصَّةِ ${seed.prophet}؟`,
        options: makeOpts(seed.virtue, pickWrongs(pools.virtues, [seed.virtue], 3))
      });
      qPool.push({
        img, focusWord: `حَرْفُ (${seed.ltr})`,
        q: `مَنْ نَبِيُّ دَرْسِ حَرْفِ (${seed.ltr})؟`,
        options: makeOpts(seed.prophet, pickWrongs(pools.prophets, [seed.prophet], 3))
      });
      qPool.push({
        img, focusWord: seed.virtue,
        q: `مَا حَرْفُ وَحْدَةِ قِصَّةِ ${seed.prophet}؟`,
        options: makeOpts(`حَرْفُ (${seed.ltr})`, pickWrongs(pools.letters, [`حَرْفُ (${seed.ltr})`], 3))
      });
      if (seed.kws && seed.kws.length) {
        const kw = seed.kws[Math.floor(Math.random() * seed.kws.length)];
        qPool.push({
          img, focusWord: seed.prophet,
          q: `أَيُّ كَلِمَةٍ مِمَّا يَلِي وَرَدَتْ فِي القِصَّةْ؟`,
          options: makeOpts(kw, pickWrongs(pools.words, seed.kws, 3))
        });
      }
      pairs = [
        { right: seed.prophet, left: seed.virtue },
        { right: `حَرْفُ (${seed.ltr})`, left: seed.prophet },
        { right: "مِنَ القِصَّةْ", left: (seed.kws && seed.kws[0]) || seed.virtue }
      ];
      const bads = shuffle(BAD_ETHICS);
      decoy = bads[0];
      basket = {
        prompt: `اخْتَرْ مَعَانِيَ قِصَّةِ ${seed.prophet}:`,
        targetCount: 3,
        items: shuffle([
          { emoji: "🌟", label: seed.virtue, good: true },
          { emoji: "📖", label: seed.prophet, good: true },
          { emoji: "✨", label: (seed.kws && seed.kws[0]) || `حَرْفُ (${seed.ltr})`, good: true },
          { emoji: "🚫", label: bads[0], good: false },
          { emoji: "⚠️", label: bads[1], good: false }
        ])
      };
    }

    else if (seed.type === "positions") {
      const wInit = seed.init[Math.floor(Math.random() * Math.max(1, seed.init.length))] || seed.ltr;
      const wMed  = seed.med[Math.floor(Math.random() * Math.max(1, seed.med.length))] || wInit;
      const wFin  = seed.fin[Math.floor(Math.random() * Math.max(1, seed.fin.length))] || wInit;
      const allLocal = [].concat(seed.init, seed.med, seed.fin);
      qPool = [
        {
          img, focusWord: "أَوَّلُ الكَلِمَةْ",
          q: `أَيْنَ جَاءَ حَرْفُ (${seed.ltr}) فِي أَوَّلِ الكَلِمَةْ؟`,
          options: makeOpts(wInit, [wMed, wFin, pickWrongs(pools.words, allLocal, 1)[0]])
        },
        {
          img, focusWord: "وَسَطُ الكَلِمَةْ",
          q: `أَيْنَ جَاءَ حَرْفُ (${seed.ltr}) فِي وَسَطِ الكَلِمَةْ؟`,
          options: makeOpts(wMed, [wInit, wFin, pickWrongs(pools.words, allLocal, 1)[0]])
        },
        {
          img, focusWord: "آخِرُ الكَلِمَةْ",
          q: `أَيْنَ جَاءَ حَرْفُ (${seed.ltr}) فِي آخِرِ الكَلِمَةْ؟`,
          options: makeOpts(wFin, [wInit, wMed, pickWrongs(pools.words, allLocal, 1)[0]])
        },
        {
          img, focusWord: wInit,
          q: `مَا مَوْضِعُ حَرْفِ (${seed.ltr}) فِي كَلِمَةِ «${wInit}»؟`,
          options: makeOpts("أَوَّلُ الكَلِمَةْ", ["وَسَطُ الكَلِمَةْ", "آخِرُ الكَلِمَةْ", "بِلَا حَرْفْ"])
        }
      ];
      pairs = [
        { right: "أَوَّلُ الكَلِمَةْ", left: wInit },
        { right: "وَسَطُ الكَلِمَةْ", left: wMed },
        { right: "آخِرُ الكَلِمَةْ", left: wFin }
      ];
      const ext = pickWrongs(pools.words, allLocal, 2);
      decoy = ext[0];
      basket = {
        prompt: `اخْتَرْ كَلِمَاتِ حَرْفِ (${seed.ltr}):`,
        targetCount: 3,
        items: shuffle([
          { emoji: "🔤", label: wInit, good: true },
          { emoji: "✍️", label: wMed, good: true },
          { emoji: "📘", label: wFin, good: true },
          { emoji: "❌", label: ext[0], good: false },
          { emoji: "❌", label: ext[1], good: false }
        ])
      };
    }

    else if (seed.type === "phonics") {
      const sh = seed.short || [];
      const lg = seed.long || [];
      const sWord = sh[Math.floor(Math.random() * Math.max(1, sh.length))] || seed.ltr;
      const lWord = lg[Math.floor(Math.random() * Math.max(1, lg.length))] || seed.ltr;
      const allPh = [].concat(sh, lg);
      qPool = [
        {
          img, focusWord: "حَرَكَةٌ قَصِيرَةْ",
          q: `أَيُّ كَلِمَةٍ جَاءَ فِيهَا حَرْفُ (${seed.ltr}) بِحَرَكَةٍ قَصِيرَةْ؟`,
          options: makeOpts(sWord, [lg[0] || "مَدّْ", lg[1] || "طَوِيلْ", pickWrongs(pools.words, allPh, 1)[0]])
        },
        {
          img, focusWord: "مَدٌّ طَوِيلْ",
          q: `أَيُّ كَلِمَةٍ جَاءَ فِيهَا حَرْفُ (${seed.ltr}) مَمْدُودًا مَدًّا طَوِيلًا؟`,
          options: makeOpts(lWord, [sh[0] || "قَصِيرْ", sh[1] || "سَرِيعْ", pickWrongs(pools.words, allPh, 1)[0]])
        },
        {
          img, focusWord: lWord,
          q: `مَا نَوْعُ صَوْتِ حَرْفِ (${seed.ltr}) فِي «${lWord}»؟`,
          options: makeOpts("مَدٌّ طَوِيلْ", ["حَرَكَةٌ قَصِيرَةْ", "سُكُونٌ مَحْضْ", "تَنْوِينٌ فَقَطْ"])
        },
        {
          img, focusWord: sWord,
          q: `مَا نَوْعُ صَوْتِ حَرْفِ (${seed.ltr}) فِي «${sWord}»؟`,
          options: makeOpts("حَرَكَةٌ قَصِيرَةْ", ["مَدٌّ بِالأَلِفْ", "مَدٌّ بِالوَاوْ", "مَدٌّ بِاليَاءْ"])
        }
      ];
      pairs = [
        { right: "حَرَكَةٌ قَصِيرَةْ", left: sWord },
        { right: "مَدٌّ بِالأَلِفْ", left: lg[0] || lWord },
        { right: "مَدٌّ طَوِيلْ", left: lg[1] || lWord }
      ];
      const wPh = pickWrongs(pools.words, allPh, 2);
      decoy = wPh[0];
      basket = {
        prompt: `اخْتَرْ كَلِمَاتِ أَصْوَاتِ حَرْفِ (${seed.ltr}):`,
        targetCount: 3,
        items: shuffle([
          { emoji: "👂", label: sWord, good: true },
          { emoji: "🎵", label: lg[0] || lWord, good: true },
          { emoji: "🔊", label: lg[1] || sh[1] || sWord, good: true },
          { emoji: "❌", label: wPh[0], good: false },
          { emoji: "❌", label: wPh[1], good: false }
        ])
      };
    }

    else if (seed.type === "math") {
      const eqs = shuffle(seed.eqs || []);
      qPool.push({
        img, focusWord: `حَرْفُ (${seed.ltr})`,
        q: `مَا قِيمَةُ حَرْفِ (${seed.ltr}) فِي حِسَابِ الجُمَّلْ؟`,
        options: makeOpts(seed.jummal, wrongNums(seed.jummal))
      });
      eqs.forEach(([lhs, rhs]) => {
        qPool.push({
          img, focusWord: `${lhs} = ؟`,
          q: `كَمْ نَاتِجُ العَمَلِيَّةْ: ${lhs} ؟`,
          options: makeOpts(rhs, wrongNums(rhs))
        });
      });
      pairs = eqs.slice(0, 3).map(([lhs, rhs]) => ({ right: lhs, left: rhs }));
      decoy = wrongNums(eqs[0] ? eqs[0][1] : seed.jummal)[0];
      basket = {
        prompt: `اخْتَرِ الأَعْدَادَ وَالمُعَادَلَاتِ الصَّحِيحَةْ:`,
        targetCount: 3,
        items: shuffle([
          { emoji: "🔢", label: seed.jummal, good: true },
          { emoji: "⚖️", label: eqs[0] ? `${eqs[0][0]} = ${eqs[0][1]}` : seed.order, good: true },
          { emoji: "✨", label: eqs[1] ? `${eqs[1][0]} = ${eqs[1][1]}` : seed.order, good: true },
          { emoji: "❌", label: "٠ + ٠ = ٩", good: false },
          { emoji: "❌", label: "نَاتِجٌ خَاطِئْ", good: false }
        ])
      };
    }

    else if (seed.type === "sports") {
      const acts = seed.actions || ["التَّنَفُّسُ الهَادِئْ"];
      const a0 = acts[0];
      const a1 = acts[1] || "تَوَازُنُ الجِسْمْ";
      qPool = [
        {
          img, focusWord: "التَّمْرِينُ الحَرَكِيّْ",
          q: `مَا المَهَارَةُ الحَرَكِيَّةُ فِي تَمْرِينِ اليَوْمْ؟`,
          options: makeOpts(a0, pickWrongs(pools.sports, acts, 3))
        },
        {
          img, focusWord: a0,
          q: `مَا ثَمَرَةُ الرِّيَاضَةِ المُنْتَظَمَةْ؟`,
          options: makeOpts("نَشَاطُ الدِّمَاغِ وَالجِسْمْ", ["الخُمُولْ", "التَّشَتُّتْ", "الكَسَلْ"])
        },
        {
          img, focusWord: "التَّوَازُنْ",
          q: `كَيْفَ نُؤَدِّي التَّمْرِينَ الحَرَكِيّْ؟`,
          options: makeOpts("بِهُدُوءٍ وَتَوَازُنْ", ["بِتَسَرُّعْ", "بِفَوْضَى", "بِشَدٍّ عَصَبِيّْ"])
        }
      ];
      pairs = [
        { right: "الحَرَكَةُ الأُولَى", left: a0 },
        { right: "المَهَارَةُ الثَّانِيَةْ", left: a1 },
        { right: "الثَّمَرَةْ", left: "نَشَاطُ الجِسْمِ وَالدِّمَاغْ" }
      ];
      decoy = "الكَسَلْ";
      basket = {
        prompt: `اخْتَرْ مَهَارَاتِ التَّمْرِينِ الرِّيَاضِيّْ:`,
        targetCount: 3,
        items: shuffle([
          { emoji: "🏃", label: a0, good: true },
          { emoji: "🌬️", label: "تَنَفُّسٌ مُنْتَظَمْ", good: true },
          { emoji: "💪", label: a1, good: true },
          { emoji: "🚫", label: "الخُمُولْ", good: false },
          { emoji: "⚠️", label: "الفَوْضَى", good: false }
        ])
      };
    }

    else if (seed.type === "science") {
      const prs = shuffle(seed.pairs || [["العُلُومْ", "المَعْرِفَةْ"]]);
      const localLeads = prs.map(p => p[0]);
      const localAns   = prs.map(p => p[1]);
      prs.forEach(([lead, kw]) => {
        qPool.push({
          img, focusWord: lead,
          q: `مَا المَفْهُومُ العِلْمِيُّ المُرْتَبِطُ بِـ«${lead}»؟`,
          options: makeOpts(kw, pickWrongs(pools.sciAnswers, localAns.concat([lead]), 3))
        });
      });
      if (seed.kws && seed.kws[0]) {
        qPool.push({
          img, focusWord: prs[0][0],
          q: `أَيُّ مَفْهُومٍ عِلْمِيٍّ وَرَدَ فِي دَرْسِ اليَوْمْ؟`,
          options: makeOpts(seed.kws[0], pickWrongs(BAD_ETHICS, [], 3))
        });
      }
      pairs = prs.slice(0, 2).map(([lead, kw]) => ({ right: lead, left: kw }));
      if (seed.kws && seed.kws[0]) {
        pairs.push({ right: "مِنْ مُفْرَدَاتِ الدَّرْسْ", left: seed.kws[0] });
      }
      while (pairs.length < 3) pairs.push({ right: "التَّفَكُّرْ", left: "العِلْمُ النَّافِعْ" });
      decoy = "تَلْوِيثُ البِيئَةْ";
      basket = {
        prompt: `اخْتَرْ مَفَاهِيمَ دَرْسِ العُلُومْ:`,
        targetCount: 3,
        items: shuffle([
          { emoji: "🔬", label: prs[0][0], good: true },
          { emoji: "🧪", label: prs[0][1], good: true },
          { emoji: "🌿", label: prs[1] ? prs[1][0] : ((seed.kws && seed.kws[0]) || "العِلْمُ النَّافِعْ"), good: true },
          { emoji: "🚫", label: "التَّلَوُّثْ", good: false },
          { emoji: "⚠️", label: "الإِهْمَالْ", good: false }
        ])
      };
    }

    else if (seed.type === "rights") {
      const kws = seed.kws || [seed.right];
      const k0 = kws[Math.floor(Math.random() * kws.length)] || seed.right;
      qPool = [
        {
          img, focusWord: "قِصَّةُ حُورَ وَنُورْ",
          q: `مَا الحَقُّ وَالأَدَبُ الَّذِي نَتَعَلَّمُهُ فِي قِصَّةِ اليَوْمْ؟`,
          options: makeOpts(seed.right, pickWrongs(pools.rights, [seed.right], 3))
        },
        {
          img, focusWord: seed.right,
          q: `أَيُّ كَلِمَةٍ وَرَدَتْ فِي قِصَّةِ حُورَ وَنُورْ؟`,
          options: makeOpts(k0, pickWrongs(BAD_ETHICS, [], 3))
        },
        {
          img, focusWord: "العَمَلُ الصَّالِحْ",
          q: `أَيُّ سُلُوكٍ نَلْتَزِمُ بِهِ فِي حَيَاتِنَا؟`,
          options: makeOpts(seed.right, pickWrongs(BAD_ETHICS, [], 3))
        }
      ];
      pairs = [
        { right: "أَدَبُ الدَّرْسْ", left: seed.right },
        { right: "مِنَ القِصَّةْ", left: k0 },
        { right: "الثَّمَرَةْ", left: "مَحَبَّةٌ وَسَكِينَةْ" }
      ];
      const bads = shuffle(BAD_ETHICS);
      decoy = bads[0];
      basket = {
        prompt: `اخْتَرِ الآدَابَ الصَّحِيحَةْ:`,
        targetCount: 3,
        items: shuffle([
          { emoji: "💎", label: seed.right, good: true },
          { emoji: "🤝", label: k0, good: true },
          { emoji: "🌸", label: "الرِّفْقُ وَالأَدَبْ", good: true },
          { emoji: "🚫", label: bads[0], good: false },
          { emoji: "⚠️", label: bads[1], good: false }
        ])
      };
    }

    return {
      questions: shuffle(qPool).slice(0, 3),
      sadaqahPairs: shuffle(pairs).slice(0, 3),
      sadaqahDecoy: decoy,
      giftBasket: basket
    };
  }

  Object.keys(data).forEach(wk => {
    const unit = data[wk];
    ["1", "2", "3", "4", "5", "6", "7"].forEach(sk => {
      if (!unit[sk] || !unit[sk].play || !unit[sk].play._qSeed) return;
      const seed = unit[sk].play._qSeed;
      Object.defineProperty(unit[sk], "play", {
        enumerable: true,
        configurable: true,
        get: function () {
          return generatePlayData(wk, sk, seed);
        }
      });
    });
  });
})(6);
